import XCTest

final class PostTests: XCTestCase {
  override func setUpWithError() throws {
    continueAfterFailure = false
  }

  func testPublishRequestedPost() {
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    let handoffAlert = springboard.alerts.firstMatch
    if handoffAlert.waitForExistence(timeout: 4) {
      let openButton = handoffAlert.buttons["Open"]
      if openButton.exists { openButton.tap() }
    }

    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    sleep(2)
    app.coordinate(withNormalizedOffset: CGVector(dx: 0.86, dy: 0.85)).tap()
    sleep(2)
    print("COMPOSER UI TREE: \(app.debugDescription)")

    let textView = app.textViews.firstMatch
    let textField = app.textFields.firstMatch
    if textView.waitForExistence(timeout: 5) {
      textView.tap()
      textView.typeText("testing hashtags #silverbench")
    } else if textField.waitForExistence(timeout: 2) {
      textField.tap()
      textField.typeText("testing hashtags #silverbench")
    } else {
      XCTFail("Could not find the post text input")
      return
    }

    sleep(1)
    print("POST-READY UI TREE: \(app.debugDescription)")
    let postButton = app.buttons.matching(NSPredicate(format: "label CONTAINS[c] %@", "Post")).firstMatch
    XCTAssertTrue(postButton.waitForExistence(timeout: 5), "Could not find the Post button")
    postButton.tap()

    let postedText = app.staticTexts["testing hashtags #silverbench"]
    XCTAssertTrue(postedText.waitForExistence(timeout: 15), "The post did not appear in the feed")
  }
}
