input.command:
cat > UITestRunner/PostTests.swift <<'EOF'
import XCTest

final class PostTests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  func testPublishRequestedPost() {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    let goHome = app.buttons["Go home"]
    if goHome.waitForExistence(timeout: 3) { goHome.tap() }
    sleep(2)
    app.coordinate(withNormalizedOffset: CGVector(dx: 0.86, dy: 0.85)).tap()
    sleep(2)
    print("COMPOSER TREE: \(app.debugDescription)")
    let textView = app.textViews.firstMatch
    let textField = app.textFields.firstMatch
    if textView.waitForExistence(timeout: 4) {
      print("FOUND TEXTVIEW: \(textView.label)")
    } else if textField.waitForExistence(timeout: 2) {
      print("FOUND TEXTFIELD: \(textField.label)")
    } else {
      XCTFail("Could not find a composer input")
    }
  }
}
EOF

