input.command:
cat > UITestRunner/PostTests.swift <<'EOF'
import XCTest

final class PostTests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }
  func testPublishRequestedPost() {
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    springboard.coordinate(withNormalizedOffset: CGVector(dx: 0.34, dy: 0.16)).tap()
    springboard.typeText("testing hashtags #silverbench")
    sleep(2)
  }
}
EOF

